// Clip to the selected source row before fitting it inside the preview.
function board(ci,ki,id='kb'){
 if(selectedModel==='mountain'&&['config','macro','saved'].includes(id))return mountainBoard(selectedVariant,id);
 if(legendMode!=='dual')return illustratedBoard(ci,ki,id);
 const photo=new URL('character-z84-palettes.webp',document.baseURI).href;
 const [offset,rowHeight]=photoRows[ki];
 const target=cases[ci].hex.match(/[a-f0-9]{2}/gi).map(v=>parseInt(v,16)/255);
 const matrix=ci===1?'.1701 .5722 .0578 0 .37 .1658 .5579 .0563 0 .35 .1488 .5006 .0505 0 .33 0 0 0 1 0':target.map(v=>`${.2126*v} ${.7152*v} ${.0722*v} 0 ${.4*v}`).join(' ')+' 0 0 0 1 0';
 const caseFilter=`<filter id="${id}finish" color-interpolation-filters="sRGB"><feColorMatrix type="matrix" values="${matrix}"/></filter>`;
 const tint=ci===0?'':`<image href="${photo}" width="1024" height="1536" mask="url(#${id}frame)" filter="url(#${id}finish)"/>`;
 const texture=surface==='brushed'?`<rect x="0" y="${offset}" width="1024" height="${rowHeight}" fill="url(#${id}brushed)" mask="url(#${id}frame)"/>`:'';
 return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 900 378" role="presentation"><defs>${caseFilter}<clipPath id="${id}row"><rect x="140" y="${offset}" width="750" height="${rowHeight}"/></clipPath><mask id="${id}frame" maskUnits="userSpaceOnUse" x="140" y="${offset}" width="750" height="${rowHeight}"><rect x="140" y="${offset}" width="750" height="${rowHeight}" fill="white"/><rect x="187" y="${offset+14}" width="664" height="${rowHeight-27}" rx="6" fill="black"/><path d="${photoCaseMasks[ki]}" fill="white" fill-rule="evenodd"/></mask><pattern id="${id}brushed" width="6" height="2" patternUnits="userSpaceOnUse"><path d="M0 .5h6" stroke="#fff" stroke-opacity=".16" stroke-width=".5"/></pattern></defs><svg x="0" y="15" width="900" height="345" viewBox="140 ${offset} 750 ${rowHeight}" preserveAspectRatio="none" overflow="hidden"><g clip-path="url(#${id}row)" style="isolation:isolate"><image href="${photo}" width="1024" height="1536"/>${tint}${texture}</g></svg></svg>`;
}
if(document.querySelector('#hero-board'))document.querySelector('#hero-board').innerHTML=board(0,3,'hero');if(document.querySelector('#color-cards'))document.querySelector('#color-cards').innerHTML=[3,4,5].map((i)=>{const c=colors[i];return `<button class="card" data-key="${i}" aria-label="Configure ${c.name} keycaps"><div class="card-top"><span>0${i+1} / ${c.ru.toUpperCase()}</span><span>EN + RU</span></div>${board(0,i,'card'+i)}<div class="card-bottom"><strong>${c.name}</strong><span>↗</span></div></button>`;}).join('');
function render(){document.querySelector('#config-board').innerHTML=board(selectedCase,selectedKey,'config');document.querySelector('#config-board').setAttribute('aria-label',`${cases[selectedCase].name} case with ${colors[selectedKey].name} keycaps, generated concept preview`);document.querySelector('#case-name').textContent=cases[selectedCase].name;document.querySelector('#key-name').textContent=colors[selectedKey].name;document.querySelector('#combo-caption').textContent=`${cases[selectedCase].name.toUpperCase()} / ${colors[selectedKey].name.toUpperCase()}`;for(const [group,items,sel] of [['cases',cases,selectedCase],['keys',colors,selectedKey]])document.querySelector('#'+group).innerHTML=items.map((c,i)=>`<button class="swatch" style="background:${c.hex}" aria-label="${c.name}" title="${c.name}" aria-pressed="${sel===i}" data-group="${group}" data-index="${i}"></button>`).join('');}
document.addEventListener('click',e=>{const sw=e.target.closest('.swatch');if(sw){if(sw.dataset.group==='cases')selectedCase=Number(sw.dataset.index);else selectedKey=Number(sw.dataset.index);render();history.replaceState(null,'',`?case=${selectedCase}&color=${selectedKey}#configure`);document.querySelector('#status').textContent='';}const card=e.target.closest('.card[data-key]');if(card){selectedKey=Number(card.dataset.key);selectedModel='character';render();document.querySelector('#configure').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});}});
const params=new URLSearchParams(location.search);const savedCase=Number(params.get('case')),savedKey=Number(params.get('color'));if(Number.isInteger(savedCase)&&savedCase>=0&&savedCase<cases.length)selectedCase=params.has('case')?savedCase:0;if(Number.isInteger(savedKey)&&savedKey>=0&&savedKey<colors.length)selectedKey=params.has('color')?savedKey:3;if(document.querySelector('#config-board'))render();
document.querySelector('#save-build')?.addEventListener('click',async()=>{let svg=board(selectedCase,selectedKey,'saved').replace(/viewBox="0 0 900 (378|450|456)"/,'viewBox="0 0 900 610"').replace(/<\/svg>$/,`<text x="28" y="520" font-family="Arial" font-size="25" fill="#252c29">formkey / ${selectedModel==='mountain'?'Matterhorn Edition / '+mountainVariants[selectedVariant].name:cases[selectedCase].name+' + '+colors[selectedKey].name}</text><text x="28" y="551" font-family="Arial" font-size="14" fill="#60685c">English + Russian · ${selectedModel==='mountain'?'Matterhorn Edition':'Character'} collection · Illustrated concept</text><text x="28" y="580" font-family="Arial" font-size="12" fill="#60685c">Availability and pricing to be confirmed.</text></svg>`);const picture=svg.match(/<image href="([^"]+)"/);if(picture){try{const response=await fetch(picture[1]);if(!response.ok)throw Error('image');const blob=await response.blob();const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(blob);});svg=svg.replaceAll(picture[1],data);}catch{document.querySelector('#status').textContent='Build card could not be downloaded. Save or share your build instead.';return;}}const url=URL.createObjectURL(new Blob([svg],{type:'image/svg+xml'}));const a=document.createElement('a');a.href=url;a.download=selectedModel==='mountain'?`formkey-matterhorn-${mountainVariants[selectedVariant].name.toLowerCase().replaceAll(' ','-')}.svg`:`formkey-${cases[selectedCase].name.toLowerCase().replaceAll(' ','-')}-${colors[selectedKey].name.toLowerCase().replaceAll(' ','-')}.svg`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);document.querySelector('#status').textContent='Your build card has been downloaded.';});

if(document.querySelector('#config-board')){
const baseRender=render;
render=function(){baseRender();renderModelControls();const caption=document.querySelector('.art-caption span:last-child');if(caption)caption.textContent=selectedModel==='mountain'?'REFERENCE PHOTO · EN + RU':'PRODUCT PICTURE · EN + RU';if(document.querySelector('#macro-board'))document.querySelector('#macro-board').innerHTML=board(selectedCase,selectedKey,'macro');document.querySelector('#legend-label').textContent={dual:'English + Russian',en:'English',blank:'Blank'}[legendMode];document.querySelector('#legend-mode').value=legendMode;document.querySelector('#surface').value=surface;document.querySelector('#switch-type').value=switchType;showBuilds();};
document.querySelectorAll('[data-start-model]').forEach(b=>b.addEventListener('click',()=>{selectedModel=b.dataset.startModel;render();updateURL();document.dispatchEvent(new Event('keyboard-model-change'));}));
document.querySelector('#keyboard-model').addEventListener('change',e=>{selectedModel=e.target.value;render();updateURL();document.dispatchEvent(new Event('keyboard-model-change'));});
document.addEventListener('click',e=>{const card=e.target.closest('[data-mountain-variant]');if(!card)return;selectedVariant=Number(card.dataset.mountainVariant);render();updateURL();});
document.querySelector('#mountain-colors').addEventListener('click',e=>{const b=e.target.closest('[data-variant]');if(!b)return;selectedVariant=Number(b.dataset.variant);render();updateURL();});
function state(){return {m:selectedModel,v:selectedVariant,c:selectedCase,k:selectedKey,l:legendMode,f:surface,s:switchType};}
function apply(b){if(!b||typeof b!=='object')return;for(const [key,max] of [['c',cases.length],['k',colors.length]]){if(!Number.isInteger(b[key])||b[key]<0||b[key]>=max)return;}selectedModel=b.m==='mountain'?'mountain':'character';selectedVariant=Number.isInteger(b.v)&&b.v>=0&&b.v<3?b.v:0;selectedCase=b.c;selectedKey=b.k;legendMode='dual';surface=b.f==='brushed'?'brushed':'satin';switchType=['linear','tactile','clicky'].includes(b.s)?b.s:'linear';render();}
function updateURL(){const u=new URL(location.href);u.searchParams.set('build',JSON.stringify(state()));u.searchParams.delete('case');u.searchParams.delete('color');history.replaceState(null,'',u);}
document.addEventListener('click',e=>{if(e.target.closest('.swatch,.card'))updateURL();});
for(const name of ['legend-mode','surface','switch-type'])document.querySelector('#'+name).addEventListener('change',e=>{if(name==='legend-mode')legendMode=e.target.value;if(name==='surface')surface=e.target.value;if(name==='switch-type')switchType=e.target.value;render();updateURL();});
let builds=[];try{builds=JSON.parse(localStorage.getItem('form-builds')||'[]');if(!Array.isArray(builds))builds=[];}catch{};
function showBuilds(){const el=document.querySelector('#saved-builds');el.replaceChildren();builds.forEach((b,i)=>{if((b.m||'character')!==selectedModel)return;const row=document.createElement('div'),btn=document.createElement('button'),del=document.createElement('button');btn.textContent=b.m==='mountain'?`Matterhorn Edition / ${mountainVariants[b.v||0].name}`:`Character / ${cases[b.c]?.name||'Case'} / ${colors[b.k]?.name||'Color'}`;btn.onclick=()=>{apply(b);updateURL();};del.textContent='×';del.setAttribute('aria-label','Delete saved build '+(i+1));del.onclick=()=>{builds.splice(i,1);persist();showBuilds();};row.append(btn,del);el.append(row);});}
function persist(){try{localStorage.setItem('form-builds',JSON.stringify(builds));return true;}catch{document.querySelector('#status').textContent='Browser storage is unavailable. Use a build link to keep this combination.';return false;}}
document.querySelector('#remember-build').onclick=()=>{builds.unshift(state());builds=builds.slice(0,12);if(persist())document.querySelector('#status').textContent='Saved to this browser.';showBuilds();};
document.querySelector('#share-build').onclick=async()=>{updateURL();try{await navigator.clipboard.writeText(location.href);document.querySelector('#status').textContent='Build link copied.';}catch{document.querySelector('#status').textContent='Copy this build link from your browser’s address bar.';}};
let audio,playing=false;
document.querySelector('#play-sound').onclick=async()=>{if(playing)return;const btn=document.querySelector('#play-sound');try{audio ||= new (window.AudioContext||window.webkitAudioContext)();await audio.resume();playing=true;btn.textContent='Playing…';btn.disabled=true;const v=Number(document.querySelector('#volume').value),type=switchType;for(let i=0;i<13;i++){let t=audio.currentTime+i*.105+Math.sin(i*3)*.015;const duration=type==='linear'?.11:type==='tactile'?.085:.065;let buf=audio.createBuffer(1,audio.sampleRate*duration,audio.sampleRate),d=buf.getChannelData(0);let seed=1234+i*735;for(let j=0;j<d.length;j++){seed=(seed*16807)%2147483647;const n=seed/1073741824-1,sec=j/audio.sampleRate;d[j]=(n*.6+Math.sin(2*Math.PI*(type==='linear'?175:type==='tactile'?310:620)*sec)*.4)*Math.exp(-sec*(type==='linear'?45:70));}let src=audio.createBufferSource(),filter=audio.createBiquadFilter(),gain=audio.createGain();src.buffer=buf;filter.type='lowpass';filter.frequency.value=type==='linear'?1200:type==='tactile'?2600:6500;gain.gain.value=v*.5;src.connect(filter).connect(gain).connect(audio.destination);src.start(t);if(type==='clicky'){const osc=audio.createOscillator(),g=audio.createGain();osc.frequency.value=3100;g.gain.setValueAtTime(v*.07,t+.018);g.gain.exponentialRampToValueAtTime(.001,t+.035);osc.connect(g).connect(audio.destination);osc.start(t+.018);osc.stop(t+.04);}}setTimeout(()=>{playing=false;btn.disabled=false;btn.textContent='▶ Hear this build';},1700);}catch{playing=false;btn.disabled=false;btn.textContent='▶ Hear this build';document.querySelector('#status').textContent='Audio is unavailable in this browser.';}};
try{const b=new URLSearchParams(location.search).get('build');if(b)apply(JSON.parse(b));}catch{}render();showBuilds();

}

// Share the selected design with the progressive 3D studio.
globalThis.getKeyboardDesign=()=>({m:selectedModel,v:selectedVariant,c:selectedCase,k:selectedKey,l:legendMode,f:surface,s:switchType});

// Colors sampled from the product pictures are shared with the 3D preview.
globalThis.getKeyboardAppearance=()=>({keycaps:colors,finishes:cases});


function renderModelControls(){
 const mountain=selectedModel==='mountain',select=document.querySelector('#keyboard-model');if(!select)return;select.value=selectedModel;
 for(const id of ['cases','keys'])document.querySelector('#'+id).closest('fieldset').hidden=mountain;
 document.querySelector('#mountain-options').hidden=!mountain;
 document.querySelector('#model-note').textContent=mountain?'Mountain artwork, cream EN + RU keycaps and a circular display. Three coordinated colors.':'Knobless Z-84. Four case finishes and six keycap palettes.';
 document.querySelector('#mountain-colors').innerHTML=mountainVariants.map((v,i)=>`<button type="button" class="variant-option" data-variant="${i}" aria-pressed="${selectedVariant===i}"><span style="background:${v.hex}"></span>${v.name}</button>`).join('');
 if(mountain){const name=mountainVariants[selectedVariant].name;document.querySelector('#config-board').setAttribute('aria-label',`Matterhorn Edition, ${name} with cream keycaps and mountain artwork`);document.querySelector('#combo-caption').textContent=`MATTERHORN EDITION / ${name.toUpperCase()}`;}
 document.querySelector('.config-controls>.eyebrow').textContent=mountain?'MATTERHORN EDITION / 02':'CHARACTER / Z-84';
 const photoThumb=document.querySelector('.matterhorn-photo-thumb');if(photoThumb&&!photoThumb.hasChildNodes())photoThumb.innerHTML=mountainBoard(2,'photo-thumb');
 const thumb=document.querySelector('.start-thumb');if(thumb&&!thumb.hasChildNodes())thumb.innerHTML=board(0,3,'start-thumb');
 document.querySelectorAll('[data-start-model]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.startModel===selectedModel)));
 const hero=document.querySelector('#hero-board');if(hero){hero.innerHTML=mountain?mountainBoard(selectedVariant,'hero'):board(selectedCase,selectedKey,'hero');hero.setAttribute('aria-label',mountain?'Matterhorn Edition keyboard with mountain artwork':`${cases[selectedCase].name} Character keyboard with ${colors[selectedKey].name} keycaps`);document.querySelector('.hero h1').innerHTML=mountain?'A new<br><em>perspective.</em>':'Your desk.<br>A little more <em>you.</em>';document.querySelector('.hero-copy p').innerHTML=mountain?'Matterhorn Edition.<br>Mountain artwork. Three signature colors.':'Familiar keys. Unexpected character.<br>A keyboard collection made to feel like you.';document.querySelector('.hero-copy .pill').innerHTML=mountain?'Configure Matterhorn <span>↗</span>':'Make it yours <span>↗</span>';document.querySelector('.hero-bottom span:first-child').textContent=mountain?'02 — MATTERHORN EDITION':'01 — THE CHARACTER COLLECTION';document.querySelector('.hero-bottom span:nth-child(2)').textContent=mountain?'EN + RU / MOUNTAIN ARTWORK / CIRCULAR DISPLAY':'Z-84 / 84 KEYS / EN + RU';}
 renderModelContent(mountain);
 document.querySelector('#recap-model').textContent=mountain?'Matterhorn Edition / 02':'Character / Z-84';
}

function renderModelContent(mountain){
 const swap=(selector,html)=>{const el=document.querySelector(selector);if(!el)return;if(el.characterContent===undefined)el.characterContent=el.innerHTML;el.innerHTML=mountain?html:el.characterContent;};
 swap('#collection .section-heading h2','Three colors. One mountain frame.');
 swap('#collection .section-heading>p','Forest green, wine red or black.<br>Cream keycaps. The same sculpted mountain frame.');
 swap('#color-cards',mountainVariants.map((v,i)=>`<button type="button" class="card" data-mountain-variant="${i}" aria-label="Choose ${v.name} Matterhorn Edition" aria-pressed="${i===selectedVariant}"><div class="card-top"><span>MATTERHORN EDITION / 0${i+1}</span><span>EN + RU</span></div>${mountainBoard(i,'matterhorn-card-'+i)}<div class="card-bottom"><strong>${v.name}</strong><span aria-hidden="true">↗</span></div></button>`).join(''));
 swap('.studio-intro ol','<li><span>01</span><a href="#keyboard-model">Matterhorn Edition</a></li><li><span>02</span><a href="#mountain-options">Choose one of three colors</a></li><li><span>03</span><a href="#configure">Explore the mountain frame</a></li>');
 swap('.config-controls>h2','Built around<br>the mountain.');
 swap('.config-controls>p','Choose your Matterhorn color.<br>Mountain-faceted frame, cream keycaps and matching artwork.');
 swap('#details .detail-grid','<article><span>01</span><h3>The mountain is in the frame.</h3><p>Angular ridges and triangular facets run across the front bezel and around the case. Real surface relief gives the enclosure its mountain character.</p></article><article><span>02</span><h3>A matching mountain landscape.</h3><p>Snow-cut artwork continues across the cream spacebar, left Shift, dark Enter and right Shift. English and Russian legends complete the layout.</p></article><article><span>03</span><h3>Three complete colorways.</h3><p>Forest green, wine red and black each pair a mountain-faceted case with cream keycaps and a green-ringed circular display.</p></article>');
 swap('#specs>div:first-child>p','Explore the faceted mountain frame, matching keycap artwork and circular display.');
 swap('#specs>div:last-child>h3','Matterhorn Edition');
 swap('#specs>div:last-child>dl','<div><dt>Layout</dt><dd>Compact, six rows + navigation column</dd></div><div><dt>Keycaps</dt><dd>Cream · English + Russian · mountain artwork</dd></div><div><dt>Frame</dt><dd>Mountain ridges and triangular surface facets</dd></div><div><dt>Colors</dt><dd>Forest green · wine red · black</dd></div><div><dt>Controls</dt><dd>Circular display · dedicated navigation and arrow keys</dd></div><div><dt>Dimensions</dt><dd>Final dimensions to be confirmed</dd></div><div><dt>Pricing</dt><dd>Concept preview · no orders available</dd></div>');
 swap('.page-heading>p','Matterhorn Edition. Three colors, one mountain-faceted frame.');
 swap('.end>.eyebrow','MAKE ROOM FOR THE MOUNTAIN');
 swap('footer>span:first-of-type','MATTERHORN EDITION');
 document.body.dataset.keyboardModel=selectedModel;
 document.querySelector('#surface').closest('label').hidden=mountain;
 const build=encodeURIComponent(JSON.stringify({m:selectedModel,v:selectedVariant,c:selectedCase,k:selectedKey,l:'dual',f:surface,s:switchType}));
 document.querySelectorAll('[data-collection-link]').forEach(a=>a.href=mountain?(document.querySelector('#collection')?'#collection':'/?build='+build+'#collection'):'/collection.html');
 document.querySelectorAll('[data-configure-link]').forEach(a=>a.href=mountain?'/configure.html?build='+build:'/configure.html');
 const nav=document.querySelector('.hero-bottom a');if(nav)nav.setAttribute('aria-label',mountain?'Explore Matterhorn colorways':'Explore the collection');
}